'use strict';
const $=id=>document.getElementById(id), types={friend:{name:'同伴',color:'#3277cf',icon:'人'},spot:{name:'景点',color:'#13876b',icon:'景'},stay:{name:'住宿',color:'#8755ad',icon:'宿'},food:{name:'餐厅',color:'#d58428',icon:'食'}};
const escapeHTML=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const uid=()=>globalThis.crypto?.randomUUID?.()||Date.now().toString(36)+Math.random().toString(36).slice(2);
function read(key,fallback){try{return JSON.parse(localStorage.getItem(key))??fallback}catch{return fallback}}
function validPoint(p){return p&&(p.color===undefined||/^#[0-9a-f]{6}$/i.test(p.color))&&typeof p.id==='string'&&typeof p.name==='string'&&p.name.length>0&&p.name.length<=80&&Object.hasOwn(types,p.type)&&typeof p.address==='string'&&p.address.length<=200&&typeof p.note==='string'&&p.note.length<=500&&((p.lng===null&&p.lat===null)||(Number.isFinite(p.lng)&&Math.abs(p.lng)<=180&&Number.isFinite(p.lat)&&Math.abs(p.lat)<=90))}
let points=read('travel-points',[]);if(!Array.isArray(points))points=[];points=points.filter(validPoint);
let filter='all',map=null,markers=[],selected=null,searchSequence=0,loading=false;
let cityValue=read('travel-city','');
function toast(message){$('toast').textContent=message;$('toast').style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('toast').style.display='none',4000)}
function save(){try{localStorage.setItem('travel-points',JSON.stringify(points));localStorage.setItem('travel-city',JSON.stringify(cityValue));return true}catch{toast('浏览器保存失败，请导出行程备份');return false}}
function pointColor(p){return /^#[0-9a-f]{6}$/i.test(p.color||'')?p.color:types[p.type].color}
function markerContent(p){const t=types[p.type];return `<div class="pin-wrap" tabindex="0" aria-label="${escapeHTML(p.name)}${p.note?'：'+escapeHTML(p.note):''}"><div class="pin" style="--c:${pointColor(p)}"><span>${t.icon}</span></div><div class="pin-tooltip" role="tooltip"><strong>${escapeHTML(p.name)}</strong><div>${escapeHTML(p.note||'暂无备注')}</div></div></div>`}
function render(){
 $('count').textContent=points.length;const visible=points.filter(p=>filter==='all'||p.type===filter);$('places').replaceChildren();
 if(!visible.length){const div=document.createElement('div');div.className='empty';div.textContent=points.length?'这个分类还没有地点。':'还没有地点。点击「添加地点」开始规划。';$('places').append(div)}
 visible.forEach(p=>{const t=types[p.type],row=document.createElement('article');row.className='place';row.tabIndex=0;row.setAttribute('role','button');row.setAttribute('aria-label','编辑 '+p.name);row.innerHTML=`<div class="dot" style="--c:${pointColor(p)}">${t.icon}</div><div class="place-body"><strong class="place-name">${escapeHTML(p.name)}</strong><p>${escapeHTML(p.address||'未填写地址')}</p>${p.note?`<p>${escapeHTML(p.note)}</p>`:''}</div>`;row.onclick=()=>openEditor(p);row.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();openEditor(p)}};$('places').append(row)});
 if(map){markers.forEach(m=>map.remove(m));markers=[];visible.filter(p=>p.lng!==null).forEach(p=>{const t=types[p.type],marker=new AMap.Marker({position:[p.lng,p.lat],title:'',content:markerContent(p),anchor:'bottom-center'});marker.on('click',()=>openEditor(p));map.add(marker);markers.push(marker)})}
}
function openEditor(p={}){$('place-id').value=p.id||'';$('editor-title').textContent=p.id?'编辑地点':'添加地点';['name','address','lng','lat','note'].forEach(k=>$(k).value=p[k]??'');const type=p.type||'spot';$('type').value=type;$('color').value=pointColor({type,color:p.color});$('editor-results').replaceChildren();$('delete-place').hidden=!p.id;$('editor').showModal()}
function finalizePlace(p){const index=points.findIndex(x=>x.id===p.id);if(index<0){points.push(p);resetFilter()}else points[index]=p;save();render();$('editor').close();toast('地点已保存');if(map&&p.lng!==null)focusPoint(p)}
function editorChoices(candidates,draft){const box=$('editor-results');box.replaceChildren();const hint=document.createElement('p');hint.textContent='找到多个位置或近似地址，点击正确位置保存：';box.append(hint);candidates.forEach(c=>{const b=document.createElement('button');b.type='button';b.innerHTML=`${escapeHTML(c.name)}<small>${escapeHTML(c.address)}${c.precise?'':' · 近似位置，请核对'}</small>`;b.onclick=()=>finalizePlace({...draft,name:draft.name||c.name.slice(0,80),address:c.address||draft.address,lng:Number(c.location.lng),lat:Number(c.location.lat)});box.append(b)})}
$('place-form').onsubmit=async e=>{e.preventDefault();const lng=$('lng').value.trim(),lat=$('lat').value.trim();if(Boolean(lng)!==Boolean(lat)){toast('请同时填写经度和纬度，或同时留空');return}const address=$('address').value.trim();let name=$('name').value.trim();if(!name&&!address){toast('请填写地点名称或地址');return}if(!name)name=address;const draft={id:$('place-id').value||uid(),name,type:$('type').value,color:$('color').value,address,lng:lng===''?null:Number(lng),lat:lat===''?null:Number(lat),note:$('note').value.trim(),updated:Date.now()};if(!validPoint(draft)){toast('请检查地点内容和坐标范围');return}if(draft.lng===null&&address&&map){$('editor-results').textContent='正在定位地址…';try{const parts=addressParts(address);const geocodes=await geocodeAddress(parts.street,parts.city);const precise=geocodes.filter(g=>g.precise);if(precise.length===1){finalizePlace({...draft,address:precise[0].address||draft.address,lng:Number(precise[0].location.lng),lat:Number(precise[0].location.lat)});return}if(precise.length>1){editorChoices(precise,draft);return}const pois=await placeSearch({city:parts.city||'全国',citylimit:!!parts.city,pageSize:10},(service,cb)=>service.search(parts.name,cb));const candidates=pois.filter(p=>p.location).map(p=>({name:p.name,address:[p.cityname,typeof p.address==='string'?p.address:''].filter(Boolean).join(' '),location:p.location,precise:true}));if(candidates.length===1){finalizePlace({...draft,name:draft.name||candidates[0].name.slice(0,80),address:candidates[0].address||draft.address,lng:Number(candidates[0].location.lng),lat:Number(candidates[0].location.lat)});return}if(candidates.length||geocodes.length){editorChoices(candidates.length?candidates:geocodes,draft);return}$('editor-results').textContent='地址未能定位，已按无坐标保存，可稍后编辑补充。';finalizePlace(draft)}catch(err){$('editor-results').textContent=err.message+'；已按无坐标保存，可稍后编辑。';finalizePlace(draft)}}else finalizePlace(draft)};
function focusPoint(p){if(p.lng===null){toast('这个地点还没有坐标，可在编辑中补充地址或坐标');return}if(!map){toast('连接高德地图后即可查看标点');return}selected=p.id;map.setZoomAndCenter(15,[p.lng,p.lat]);const d=$('detail');d.hidden=false;d.innerHTML=`<h3>${escapeHTML(p.name)}</h3><p>${escapeHTML(p.address)}</p><p>${escapeHTML(p.note)}</p><p>${p.type==='friend'?'同伴位置由你手动记录，非实时定位':'从这里出发，看看附近有什么'}</p><button id="nearby">附近景点（3 公里内）</button><button id="edit-selected">编辑</button><button id="close-detail">关闭</button><div id="nearby-results"></div>`;$('edit-selected').onclick=()=>openEditor(p);$('close-detail').onclick=()=>d.hidden=true;$('nearby').onclick=()=>nearby(p)}
function placeSearch(options,invoke){return new Promise((resolve,reject)=>{const timeout=setTimeout(()=>reject(Error('搜索超时，请检查网络后重试')),15000);const service=new AMap.PlaceSearch(options);invoke(service,(status,result)=>{clearTimeout(timeout);if(status==='complete'&&result?.poiList)resolve(result.poiList.pois||[]);else if(status==='no_data')resolve([]);else reject(Error('高德搜索失败，请检查 Key、密钥及域名配置'+(typeof result?.info==='string'?'（'+result.info+'）':'')))})})}
function showResults(container,pois){container.replaceChildren();const valid=pois.filter(p=>p.location);if(!valid.length){container.textContent='没有找到结果，请换一个更具体的地址或城市。';return}valid.forEach(p=>{const b=document.createElement('button');b.innerHTML=`${escapeHTML(p.name)}<small>${escapeHTML([p.cityname,typeof p.address==='string'?p.address:''].filter(Boolean).join(' '))}</small>`;b.onclick=()=>openEditor({name:p.name.slice(0,80),address:[p.cityname,typeof p.address==='string'?p.address:''].filter(Boolean).join(' ').slice(0,200),lng:p.location.lng,lat:p.location.lat,type:'spot'});container.append(b)})}
function addressParts(query){const match=query.match(/^(.*?)(?:（|\()([^）)]+)(?:）|\))\s*$/);const city=query.match(/(?:北京市|上海市|天津市|重庆市|[^省自治区\s]{2,}市)/);return {city:city?city[0].replace(/^.*省/,''):cityValue.trim(),street:match?query.slice(0,query.indexOf('区')+1)+match[2]:query,name:match?match[1]:query}}
function geocodeAddress(address,city){return new Promise((resolve,reject)=>{const timer=setTimeout(()=>reject(Error('地址定位超时，请重试')),15000);new AMap.Geocoder({city:city||'全国'}).getLocation(address,(status,result)=>{clearTimeout(timer);if(status==='complete')resolve((result.geocodes||[]).filter(g=>g.location).map(g=>({name:address,address:g.formattedAddress||address,location:g.location,level:g.level,precise:['门牌号','兴趣点'].includes(g.level)})));else if(status==='no_data')resolve([]);else reject(Error('地址定位失败，请检查高德配置后重试'))})})}
function resetFilter(){filter='all';document.querySelectorAll('[data-filter]').forEach(b=>b.classList.toggle('active',b.dataset.filter==='all'))}
async function nearby(p){const button=$('nearby'),target=$('nearby-results');button.disabled=true;target.textContent='正在查找附近景点…';try{const pois=await placeSearch({type:'风景名胜',pageSize:10},(service,cb)=>service.searchNearBy('',[p.lng,p.lat],3000,cb));if(target.isConnected)showResults(target,pois)}catch(err){if(target.isConnected)target.textContent=err.message}finally{if(button.isConnected)button.disabled=false}}
function openConfig(){const c=read('travel-map-config',{});if(c.key)$('api-key').value=c.key;if(c.code)$('security-code').value=c.code;$('remember').checked=!!c.key;$('config-error').textContent='';$('config').showModal()}
function loadSDK(key,code){return new Promise((resolve,reject)=>{if(window.AMap){resolve();return}window._AMapSecurityConfig={securityJsCode:code};const script=document.createElement('script');script.src='https://webapi.amap.com/maps?v=2.0&key='+encodeURIComponent(key)+'&plugin=AMap.PlaceSearch,AMap.Geocoder,AMap.ToolBar,AMap.Scale';let done=false;const timer=setTimeout(()=>finish(Error('地图加载超时，请检查网络后重试')),20000);function finish(err){if(done)return;done=true;clearTimeout(timer);script.onload=null;script.onerror=null;if(err){script.remove();reject(err)}else resolve()}script.onload=()=>finish(window.AMap?null:Error('地图未能初始化，请检查 Key 和密钥'));script.onerror=()=>finish(Error('无法连接高德地图，请检查网络'));document.head.append(script)})}
async function connect(key,code){if(loading)return;loading=true;$('save-config').disabled=true;$('map-status').textContent='正在连接高德地图…';try{await loadSDK(key,code);map=new AMap.Map('map',{zoom:11,center:[120.1551,30.2741],resizeEnable:true});map.addControl(new AMap.ToolBar({position:'RB'}));map.addControl(new AMap.Scale());map.on('rightclick',e=>openEditor({lng:e.lnglat.lng,lat:e.lnglat.lat}));$('map').addEventListener('contextmenu',e=>e.preventDefault());$('map-empty').hidden=true;$('map-status').textContent='高德地图 · 右键空白处添加地点';render();fit();if($('config').open)$('config').close();toast('地图已加载；若地址搜索失败，请检查密钥配置')}catch(err){$('map-status').textContent='地图连接失败';$('config-error').textContent=err.message;toast(err.message)}finally{loading=false;$('save-config').disabled=false}}
$('config-form').onsubmit=e=>{e.preventDefault();const key=$('api-key').value.trim(),code=$('security-code').value.trim();if(!key||!code)return;if(window.AMap){toast('修改配置后需要刷新页面');try{if($('remember').checked)localStorage.setItem('travel-map-config',JSON.stringify({key,code}));else localStorage.removeItem('travel-map-config')}catch{}location.reload();return}try{if($('remember').checked)localStorage.setItem('travel-map-config',JSON.stringify({key,code}));else localStorage.removeItem('travel-map-config')}catch{toast('无法记住配置，本次连接仍可继续')}connect(key,code)};
$('forget').onclick=()=>{try{localStorage.removeItem('travel-map-config')}catch{}$('api-key').value='';$('security-code').value='';$('remember').checked=false;toast('已清除保存的配置；刷新页面后当前连接将断开')};
function fit(){if(!map){toast('请先连接高德地图');return}if(!markers.length){toast('当前分类没有带坐标的地点');return}map.setFitView(markers,false,[70,70,100,70],16)}
$('fit').onclick=fit;$('settings').onclick=openConfig;$('connect').onclick=openConfig;$('add').onclick=()=>openEditor();
document.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>$(b.dataset.close).close());
document.querySelectorAll('dialog').forEach(d=>d.addEventListener('click',e=>{if(e.target!==d)return;const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close()}));
document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;document.querySelectorAll('[data-filter]').forEach(x=>x.classList.toggle('active',x===b));$('detail').hidden=true;render()});
$('export').onclick=()=>{const blob=new Blob([JSON.stringify({version:1,city:cityValue,points},null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='一起出发-行程.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('已导出行程，包含地点和同伴位置，请仅分享给同行朋友')};
$('import').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>2*1024*1024)throw Error('文件过大，请选择 2 MB 以内的行程');const data=JSON.parse(await file.text());if(data.version!==1||!Array.isArray(data.points)||data.points.length>1000||!data.points.every(validPoint)||typeof data.city!=='string'||data.city.length>40)throw Error('行程格式不正确，请使用本工具导出的 JSON 文件');if(points.length&&!confirm('导入将替换当前行程。建议先导出备份，是否继续？'))return;points=data.points.map(p=>({id:uid(),name:p.name,type:p.type,color:pointColor(p),address:p.address,lng:p.lng,lat:p.lat,note:p.note,updated:Date.now()}));cityValue=data.city;$('detail').hidden=true;save();render();if(map&&markers.length)fit();toast('行程已导入')}catch(err){toast(err.message)}finally{e.target.value=''}};
render();const config=read('travel-map-config',{});if(config.key&&config.code)connect(config.key,config.code);


$('delete-place').onclick=()=>{const id=$('place-id').value;const p=points.find(x=>x.id===id);if(!p)return;if(confirm(`删除「${p.name}」？`)){points=points.filter(x=>x.id!==id);if(selected===id)$('detail').hidden=true;save();render();$('editor').close();toast('已删除')}};
$('type').onchange=()=>{$('color').value=types[$('type').value].color};
